// TH14 v1.00b st05mbs.ecl::MBossCard1 (src 135-190) + MBossCard1_at (src 192-254).
// Shell: control at (0,0) with no body; real boss enters at the inherited anchor (0,128)
// (MBoss entry already finished its movePosTime to (0,128)).
// Source time base: card frame = source T + 120 (opening buffer); source T0 = boss spawn.

const TIME_LIMIT: int = 2124;      // 120 opening + 2000 source window + 4 start slack
const OPENING_BUFFER: int = 120;
const SRC_LIMIT: int = 1500;       // src 152 setInterrupt(0,0,1500) / src 155 spell timer
const TH14_OVAL: int = 672;        // TH14 src type 20 -> target type 20 (row base 672), color 1

// src 211 etEx(0,1,4096,[-1],15): one arm with 2/2/3/4 wall events, mask 15 = all walls.
// Source reads this as 反弹 in the task/split notes; target bounce_arm.
// Engine stores the remaining count in a 2-bit field (max 3), so L's source 4 is capped at 3
// (same documented cap as th18_s4_b2).
xformdef TH14_BOUNCE2 { bounce_arm(15, 2); }
xformdef TH14_BOUNCE3 { bounce_arm(15, 3); }

// moveRand(60,4,1.0) recipe from transcribe/th18/movement.md, limits adapted to src 160
// moveLimit(0,128,280,64): actual x in [-140,140], y in [96,160]; direction inner zone
// x +-70, y 112..144 (center +- width/4, height/4).
// Enemy slots: int0 = next-step counter, fx0/fx1 = logical unit vector (movement recipe);
// int1 = source $I0, fx2 = source %F0.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Signed unit random * pi (unwrapped BAM ints), then the native x-side branches.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // This branch is deliberately not normalized before the y fabs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05 rad -> +-522 BAM around +-16384.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

// Source waits inside this attack are clipped to the 1500-frame native timeout so no
// wave fires after it; the boss then runs the MBossEscape timeout tail.
sub src_wait(n: int) {
    var m: int = n;
    var remain: int = SRC_LIMIT - $self_age;
    if remain < m { m = remain; }
    if m > 0 { wait(m); }
}

// src 192-254 MBossCard1_at, synchronous on the boss task.
// src 195-199/217: the initial etAngle(pi/2, 0.032724924) config is overwritten by the
// loop-head etAngle before the first etOn, so it never fires; only the later angles are used.
sub card_at() {
    var rank: int = global(GVAR_RANK);
    sh_reset(0);
    sh_sprite(0, TH14_OVAL, 1);
    sh_aim(0, 0);                 // src 196 etAim(0,1): fixed-direction fan
    sh_ring(0, 0);
    sh_count(0, 2, 1);            // src 198 etCount(0,2,1)
    sh_speed(0, 3fx, 0fx);        // src 200 etSpeed(3,1), single layer -> 3
    // src 212 etDist(32) with src 201 ANIM a=1 birth displacement -4*3 = -12 along the
    // bullet angle (birth anim stage itself omitted per policy).
    sh_dist(0, 20fx);
    if rank >= RANK_HARD { sh_xform(0, TH14_BOUNCE3); }
    else { sh_xform(0, TH14_BOUNCE2); }

    // src 216-221: 13 waves, fixed -pi/2, spread 1.047198 rad, wait 6.
    var spread: int = 10923;      // 1.047198 rad
    var i: int = 0;
    while i < 13 && $self_age < SRC_LIMIT {
        sh_angle(0, 270deg, spread as angle);
        sh_fire(0);
        src_wait(6);
        i = i + 1;
    }
    // src 225-231: 9 waves, spread shrinking 0.1496 rad after each shot, wait 6.
    i = 0;
    while i < 9 && $self_age < SRC_LIMIT {
        sh_angle(0, 270deg, spread as angle);
        sh_fire(0);
        spread = spread - 1560;   // 0.1496 rad
        src_wait(6);
        i = i + 1;
    }
    // src 232-252: G single bullets at -pi/2 + RANDF2*0.5235988, per-rank wait.
    sh_count(0, 1, 1);
    var g: int = 40;
    var dt: int = 2;
    if rank == RANK_EASY { g = 30; dt = 2; }
    else if rank == RANK_NORMAL { g = 60; dt = 1; }
    i = 0;
    while i < g && $self_age < SRC_LIMIT {
        var u: fx = (rand(65536) - 32768) as fx / 32768;
        var off: int = (5461fx * u) as int;   // +-0.5235988 rad
        sh_angle(0, 270deg + (off as angle), 0deg);
        sh_fire(0);
        src_wait(dt);
        i = i + 1;
    }
}

async sub boss() {
    set_invuln(65535);
    set_hitbox(48fx);             // src MBoss common entry setHitbox/setHurtbox 48
    set_hurtbox(48fx);

    // src 138-153 entry: timerReset (T0 = spawn), killAllAsync/enmKillAll/Ecl_EtBreak/
    // spellEnd/funcSet(0)/laserCancel only clean the previous attack; this standalone
    // shell starts with no old async, enemies, bullets or lasers, so they have nothing
    // to act on here. The timeout path is kept below.
    var rank: int = global(GVAR_RANK);
    set_self_int(1, 20);          // src 168 diffI($I0,20,20,20,24); written, not read in this card
    if rank >= RANK_LUNATIC { set_self_int(1, 24); }

    move_to(60, 0fx, 160fx, EASE_QUAD_OUT);   // src 159 movePosTime(60,4,0,160)
    wait(150);                                 // src 161/164/166 +60/+120/+30 -> T150
    set_self_fx(2, 0.034907fx);                // src 169 %F0

    var sgn: fx = 1fx;
    while $self_age < SRC_LIMIT {
        sgn = 0fx - sgn;                       // src 172 %F0 = %F0 * -1
        set_self_fx(2, sgn * 0.034907fx);
        card_at();                             // src 174 @MBossCard1_at()
        if rank == RANK_EASY { src_wait(30); } else { src_wait(0); }  // src 175-184
        if $self_age < SRC_LIMIT {
            card_move_rand();                  // src 185 moveRand(60,4,1.0)
            var i: int = 0;
            while i < 60 && $self_age < SRC_LIMIT {
                wait(1);
                card_arm_next_step();
                i = i + 1;
            }
            src_wait(60);                      // src 186
        }
    }

    // src 288-309 MBossEscape timeout tail: TIMEOUT != 0 -> etClear(640), move out,
    // wait 60, delete. The HP path (MBossDead) needs DPS, which this shell does not model.
    clear_bullets();
    move_to(60, 224fx, 64fx, EASE_QUAD_OUT);
    wait(60);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2200, 0, 0, 0, boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
